            <article
              key={idx}
              aria-label={`${m.title} card`}
              data-agent-role="card"
              data-agent-context={`metric-${idx}`}
            >
              <MetricCard
                title={m.title}
                value={m.value}
                change={m.change}
                trend={m.trend}
                description={m.description}
                sparklineData={m.sparkline}
                icon={<m.icon className="w-6 h-6" />}
                color={m.color}
              />
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

export default MetricsSection;

