// --- FILE: src/components/MetricCard.tsx ---
function MetricCard({
  title,
  value,
  change,
  changeType = "positive",
  sparklineData,
  icon,
  description
}: {
  title: string;
  value: string | number;
  change: string;
  changeType: "positive" | "negative";
  sparklineData: number[];
  icon: React.ReactNode;
  description: string;
}) {
  return (
    <Card className="border border-slate-200 shadow-sm hover:shadow-md transition-shadow">
      <CardContent className="p-6">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-lg bg-blue-100 flex items-center justify-center">
              {React.isValidElement(icon) ? icon : <div>Icon</div>}
            </div>
            <div>
              <CardTitle className="text-slate-900 font-medium">{title}</CardTitle>
              <CardDescription className="text-sm text-slate-500">{description}</CardDescription>
            </div>
          </div>
          <div className="flex items-center gap-1 text-sm font-medium">
            <span className={changeType === "positive" ? "text-emerald-600" : "text-red-600"}>
              {changeType === "positive" ? (
                <>
                  <TrendingUp className="w-4 h-4 inline" /> {change}
                </>
              ) : (
                <>
                  <TrendingDown className="w-4 h-4 inline" /> {change}
                </>
              )}
            </span>
          </div>
        </div>

        <div className="text-3xl font-bold text-slate-900 mb-2">{value}</div>

        <div className="w-full h-2 bg-slate-100 rounded-full mt-4">
          {sparklineData.map((dataPoint, index) => (
            <div
              key={index}
              className="relative h-2 rounded-full"
              style={{
                width: `${dataPoint * 2}%`,
                backgroundColor: index % 2 === 0 ? "#049DBF" : "#049DBF/20",
                marginRight: "1%",
                transform: `translate(${index * 5}%, 0)`,
                borderRadius: "2px"
              }}
            />
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

