// --- FILE: src/components/AIKitTable.tsx ---
function AIKitTable({
  columns,
  data,
  onSort,
  sortColumn,
  sortDirection
}: {
  columns: Array<{ key: string; label: string; render?: (row: any) => React.ReactNode }>;
  data: any[];
  onSort: (column: string) => void;
  sortColumn: string;
  sortDirection: "asc" | "desc";
}) {
  return (
    <div className="overflow-x-auto bg-white rounded-xl border border-slate-200">
      <Table>
        <TableHeader>
          <TableRow>
            {columns.map((column, index) => (
              <TableHead
                key={index}
                className="py-3 px-4 text-left text-sm font-medium text-slate-500 border-r border-slate-200"
              >
                <div
                  className="flex items-center cursor-pointer hover:text-slate-700"
                  onClick={() => onSort(column.key)}
                >
                  {column.label}
                  {column.key === sortColumn && (
                    <ChevronUp
                      className={`w-4 h-4 ml-1 ${ sortDirection === "asc" ? "text-blue-600" : "text-slate-400" }`}
                    />
                  )}
                  {column.key === sortColumn && (
                    <ChevronDown
                      className={`w-4 h-4 ml-1 ${ sortDirection === "desc" ? "text-blue-600" : "text-slate-400" }`}
                    />
                  )}
                </div>
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {data.map((row, index) => (
            <TableRow
              key={index}
              className={`${index % 2 === 0 ? "bg-slate-50" : "bg-white"} hover:bg-slate-100`}
            >
              {columns.map((column) => (
                <TableCell key={column.key} className="py-3 px-4 border-r border-slate-200 text-sm">
                  {column.render ? column.render(row) : row[column.key]}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

