// --- FILE: src/components/TemperatureChart.tsx ---
function TemperatureChart({ data }: { data: any[] }) {
  const chartData = data.map((day: any, index: number) => ({
    day: index + 1,
    max: day.temp.max,
    min: day.temp.min
  }));

  return (
    <div className="h-96">
      <ResponsiveContainer width="100%" height="100%">
        <AreaChart data={chartData}>
          <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
          <XAxis dataKey="day" tickFormatter={(value) => `Day ${value}`} />
          <YAxis domain={[40, 100]} />
          <Tooltip contentStyle={{ backgroundColor: '#1f2937', border: 'none' }} />
          <Legend />
          <Area
            type="monotone"
            dataKey="max"
            stroke="#3b82f6"
            fill="#60a5fa"
            name="Max Temp"
          />
          <Area
            type="monotone"
            dataKey="min"
            stroke="#06b6d4"
            fill="#0ea5e9"
            name="Min Temp"
          />
        </AreaChart>
      </ResponsiveContainer>
    </div>
  )
}

