function ExpenseTracker() {
  const [expenses, setExpenses] = useState([
    { id: 1, category: 'Groceries', amount: 45.20, date: '2023-10-15' },
    { id: 2, category: 'Transportation', amount: 22.50, date: '2023-10-14' },
    { id: 3, category: 'Entertainment', amount: 35.00, date: '2023-10-13' },
  ]);

  const [newExpense, setNewExpense] = useState({
    category: '',
    amount: 0,
    date: new Date().toISOString().split('T')[0]
  });

  const [sortConfig, setSortConfig] = useState({ key: 'date', direction: 'desc' });
  const [searchTerm, setSearchTerm] = useState('');

  const categories = [
    'Groceries', 'Transportation', 'Entertainment', 'Utilities',
    'Healthcare', 'Food', 'Shopping', 'Travel', 'Bills', 'Other'
  ];

  const categoryColors = {
    Groceries: '#F59E0B', Transportation: '#3B82F6', Entertainment: '#8B5CF6',
    Utilities: '#10B981', Healthcare: '#EF4444', Food: '#FACC15',
    Shopping: '#EC4899', Travel: '#14B8A6', Bills: '#6B7280', Other: '#60A5FA'
  };

  const handleSort = (key) => {
    let direction = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newId = expenses.length > 0 ? Math.max(...expenses.map(e => e.id)) + 1 : 1;
    setExpenses([...expenses, { ...newExpense, id: newId }]);
    setNewExpense({ category: '', amount: 0, date: new Date().toISOString().split('T')[0] });
  };

  const filteredExpenses = expenses.filter(expense =>;
    expense.category.toLowerCase().includes(searchTerm.toLowerCase()) ||
    expense.amount.toString().includes(searchTerm)
  );

  const sortedExpenses = filteredExpenses.sort((a, b) => {
    if (a[sortConfig.key] < b[sortConfig.key]) {
      return sortConfig.direction === 'asc' ? -1 : 1;
    }
    if (a[sortConfig.key] > b[sortConfig.key]) {
      return sortConfig.direction === 'asc' ? 1 : -1;
    }
    return 0;
  });

  // Calculate category totals for chart
  const categoryTotals = categories.map(category => {
    const total = expenses;
      .filter(expense => expense.category === category)
      .reduce((sum, expense) => sum + expense.amount, 0);
    return { category, total };
  });

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <AppHeader />

      <div className="max-w-7xl mx-auto">
        <Card className="mb-8">
          <CardHeader>
            <CardTitle>Add New Expense</CardTitle>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <Label htmlFor="category">Category</Label>
                  <Select value={newExpense.category} onValueChange={(value) => setNewExpense({...newExpense, category: value})}>
                    <SelectTrigger>
                      <SelectValue placeholder="Select category" />
                    </SelectTrigger>
                    <SelectContent>
                      {categories.map(category => (
                        <SelectItem key={category} value={category}>{category}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label htmlFor="amount">Amount ($)</Label>
                  <Input
                    type="number"
                    id="amount"
                    value={newExpense.amount}
                    onChange={(e) => setNewExpense({...newExpense, amount: parseFloat(e.target.value) || 0})}
                    placeholder="0.00"
                    min="0"
                    step="0.01"
                    className="w-full"
                  />
                </div>
                <div>
                  <Label htmlFor="date">Date</Label>
                  <Input
                    type="date"
                    id="date"
                    value={newExpense.date}
                    onChange={(e) => setNewExpense({...newExpense, date: e.target.value})}
                    className="w-full"
                  />
                </div>
              </div>
              <Button type="submit" className="ml-auto">
                <Plus className="w-4 h-4 mr-2" /> Add Expense
              </Button>
            </form>
          </CardContent>
        </Card>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Search and sorting controls */}
          <div className="lg:col-span-1">
            <Card>
              <CardContent className="space-y-4">
                <div>
                  <Label htmlFor="search">Search Expenses</Label>
                  <Input
                    id="search"
                    placeholder="Search by category or amount"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full"
                  />
                </div>
                <div className="space-y-2">
                  <div className="flex items-center justify-between p-2 cursor-pointer hover:bg-gray-100 rounded"
                       onClick={() => handleSort('date')}>
                    <span>Sort by Date</span>
                    {sortConfig.key === 'date' && (
                      sortConfig.direction === 'asc' ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />
                    )}
                  </div>
                  <div className="flex items-center justify-between p-2 cursor-pointer hover:bg-gray-100 rounded"
                       onClick={() => handleSort('amount')}>
                    <span>Sort by Amount</span>
                    {sortConfig.key === 'amount' && (
                      sortConfig.direction === 'asc' ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Expense chart */}
          <div className="lg:col-span-2">
            <Card>
              <CardHeader>
                <CardTitle>Expenses by Category</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="h-96 w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={categoryTotals}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                      <XAxis dataKey="category" stroke="#4b5563" fontSize={12} />
                      <YAxis stroke="#4b5563" fontSize={12} />
                      <Tooltip />
                      <Legend />
                      <Bar
                        dataKey="total"
                        fill="#8B5CF6"
                        radius={[4, 4, 0, 0]}
                      >
                        {categoryTotals.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={categoryColors[entry.category] || '#8B5CF6'} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>

        {/* Expense table */}
        <Card className="mt-8">
          <CardHeader>
            <CardTitle>Recent Expenses</CardTitle>
            <CardDescription>Track your spending over time</CardDescription>
          </CardHeader>
          <CardContent>
            <AIKitTable
              columns={[
                { key: 'category', label: 'Category', render: (data) => (
                  <div className="flex items-center gap-2">
                    <div className={`w-3 h-3 rounded-full ${categoryColors[data.category] || '#8B5CF6'}`} />
                    {data.category}
                  </div>
                )},
                { key: 'amount', label: 'Amount ($)', render: (data) => <div className="font-medium">${data.amount.toFixed(2)}</div> },
                { key: 'date', label: 'Date', render: (data) => <div>{new Date(data.date).toLocaleDateString()}</div> },
                { key: 'actions', label: 'Actions', render: (data) => (
                  <div className="flex gap-2">
                    <Button variant="ghost" size="sm" className="p-1">
                      <Edit className="w-4 h-4" />
                    </Button>
                    <Button variant="ghost" size="sm" className="p-1 text-red-500">
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                )},
              ]}
              data={sortedExpenses}
              onSort={handleSort}
              sortColumn={sortConfig.key}
              sortDirection={sortConfig.direction}
            />
          </CardContent>
        </Card>

        {/* Summary metrics */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mt-8">
          <MetricCard
            title="Total Expenses"
            value={`$${expenses.reduce((sum, expense) => sum + expense.amount, 0).toFixed(2)}`}
            icon={<DollarSign className="w-5 h-5" />}
          />
          <MetricCard
            title="Categories"
            value={categories.filter(category =>
              expenses.some(expense => expense.category === category)
            ).length}
            icon={<Tag className="w-5 h-5" />}
          />
          <MetricCard
            title="Recent Expense"
            value={expenses.length > 0 ? `$${expenses[0].amount.toFixed(2)}` : '0.00'}
            icon={<Calendar className="w-5 h-5" />}
          />
          <MetricCard
            title="Average Expense"
            value={expenses.length > 0 ?
              `$${(expenses.reduce((sum, expense) => sum + expense.amount, 0) / expenses.length).toFixed(2)}` : '0.00'}
            icon={<TrendingUp className="w-5 h-5" />}
          />
        </div>
      </div>
    </div>
  );
}

