  ];

  const handlePlayPause = () => {
    setIsPlaying(!isPlaying);
  };

  const handleNext = () => {
    if (!isShuffling) {
      setCurrentSongIndex(prev => (prev + 1) % songs.length);
      setProgress(0);
    } else {
      const shuffled = [...songs].sort(() => Math.random() - 0.5);
      setCurrentSongIndex(Math.min(shuffled.findIndex(s => s.id === songs[currentSongIndex].id) + 1, shuffled.length - 1));
    }
  };

  const handlePrev = () => {
    if (!isShuffling) {
      setCurrentSongIndex(prev => (prev - 1 + songs.length) % songs.length);
      setProgress(0);
    } else {
      const shuffled = [...songs].sort(() => Math.random() - 0.5);
      setCurrentSongIndex(shuffled.findIndex(s => s.id === songs[currentSongIndex].id) - 1 >= 0 ?
        shuffled.findIndex(s => s.id === songs[currentSongIndex].id) - 1 :
        shuffled.length - 1);
    }
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
