            <span className="text-sm text-slate-400">{formatTime(currentSong.duration)}</span>
          </div>
        </div>

        {/* Playback Controls */}
        <div className="px-6 mb-6 flex items-center gap-6">
          <Button
            variant="ghost"
            size="icon"
            className="w-10 h-10 rounded-full bg-white/10 hover:bg-white/20 text-white transition-colors"
            onClick={handlePrev}
            aria-label="Previous song"
          >
            <ArrowLeft className="w-5 h-5" />
          </Button>

          <Button
            variant={isPlaying ? "secondary" : "default"}
            size="icon"
            className="w-12 h-12 rounded-full bg-blue-600 hover:bg-blue-700 text-white transition-colors flex items-center justify-center"
            onClick={handlePlayPause}
            aria-label={isPlaying ? "Pause" : "Play"}
          >
            {isPlaying ? (
              <Pause className="w-6 h-6" />
            ) : (
              <Play className="w-6 h-6" />
            )}
          </Button>

          <Button
            variant="ghost"
            size="icon"
            className="w-10 h-10 rounded-full bg-white/10 hover:bg-white/20 text-white transition-colors"
