                className="flex items-center gap-1 text-sm text-slate-400 hover:text-white"
                onClick={() => setIsRepeating(!isRepeating)}
                aria-label={isRepeating ? "Disable repeat" : "Enable repeat"}
              >
                <Repeat className="w-4 h-4" />
                <span>{isRepeating ? "Repeat Off" : "Repeat On"}</span>
              </Button>
            </div>
          </div>
        </div>

        {/* Volume Control */}
        <div className="px-6 py-4 flex items-center gap-4">
          <span className="text-sm text-slate-400">Volume</span>
          <Progress
            value={volume}
            className="flex-1 h-2"
            onClick={(e) => setVolume(e.currentTarget.value)}
          />
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="icon"
              className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 text-white"
              onClick={() => setVolume(prev => Math.max(prev - 5, 0))}
              aria-label="Decrease volume"
            >
              <Volume2 className="w-4 h-4" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 text-white"
              onClick={() => setVolume(prev => Math.min(prev + 5, 100))}
              aria-label="Increase volume"
            >
              <VolumeUp className="w-4 h-4" />
            </Button>
          </div>
        </div>

        {/* Queue Section */}
        <div className="px-6 pt-6">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold">Queue ({songs.length} songs)</h3>
