                onClick={() => {
                  setCurrentSongIndex(index);
                  setProgress(0);
                }}
              >
                <div className="w-8 h-8 rounded flex items-center justify-center text-sm font-medium">
                  {index + 1}
                </div>
                <div className="w-12 h-12 rounded overflow-hidden flex-shrink-0">
