function TeamCard({ name, role, department, status, avatar, bio, skills }) {
  const getStatusBadge = () => {
    switch(status) {
      case 'active': return {
        text: 'Available',
        bg: 'bg-green-100',
        textColor: 'text-green-800',
        icon: <Check className="w-4 h-4 text-green-600" />
      };
      case 'busy': return {
        text: 'Busy',
        bg: 'bg-yellow-100',
        textColor: 'text-yellow-800',
        icon: <Clock className="w-4 h-4 text-yellow-600" />
      };
      case 'vacation': return {
        text: 'On Vacation',
        bg: 'bg-blue-100',
        textColor: 'text-blue-800',
        icon: <Sun className="w-4 h-4 text-blue-600" />
      };
      case 'offline': return {
        text: 'Offline',
        bg: 'bg-gray-100',
        textColor: 'text-gray-800',
        icon: <Moon className="w-4 h-4 text-gray-600" />
      };
      default: return {
        text: 'Available',
        bg: 'bg-green-100',
        textColor: 'text-green-800',
        icon: <Check className="w-4 h-4 text-green-600" />
      };
    }
  };

  const statusBadge = getStatusBadge();

  return (
    <Card className="border border-slate-200 hover:shadow-lg transition-shadow duration-200">
      <CardContent className="p-6">
        <div className="flex items-center gap-4">
          <AIKitAvatar
            name={name}
            status={status}
            size="lg"
            className="border-2 border-slate-200"
          />

          <div className="flex-1">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-lg font-semibold text-slate-900">{name}</h3>
                <p className="text-sm text-slate-500">{role}</p>
              </div>
              <Badge className={`text-xs ${statusBadge.textColor}`}>
                {statusBadge.icon} {statusBadge.text}
              </Badge>
            </div>

            <div className="mt-3 flex items-center gap-2">
              <div className="flex items-center gap-1 text-sm text-slate-500">
                <Building2 className="w-3 h-3 text-slate-400" />
                {department}
              </div>
              <div className="flex items-center gap-1 text-sm text-slate-500">
                <Users2 className="w-3 h-3 text-slate-400" />
                Team Member
              </div>
            </div>

            <div className="mt-4">
              <p className="text-sm text-slate-600">{bio}</p>
              <div className="mt-2 flex flex-wrap gap-2">
                {skills.map((skill, index) => (
                  <Badge
                    key={index}
                    variant="secondary"
                    className="text-xs px-2 py-0.5"
                  >
                    {skill}
                  </Badge>
                ))}
              </div>
            </div>
          </div>
        </div>

        <div className="mt-6 pt-6 border-t border-slate-100 flex justify-end space-x-4">
          <Button
            variant="outline"
            size="sm"
            className="text-slate-600 hover:text-slate-900 hover:bg-slate-50"
          >
            <MessageSquare className="w-4 h-4 mr-2" />
            Message
          </Button>
          <Button
            variant="outline"
            size="sm"
            className="text-slate-600 hover:text-slate-900 hover:bg-slate-50"
          >
            <Phone className="w-4 h-4 mr-2" />
            Call
          </Button>
          <Button
            variant="outline"
            size="sm"
            className="text-slate-600 hover:text-slate-900 hover:bg-slate-50"
