// --- FILE: src/components/UsageMetric.tsx ---
function UsageMetric({ title, value, max, unit }) {
  const percentage = Math.round((value / max) * 100);

  return (
    <div className="space-y-2">
      <div className="flex justify-between items-center">
        <p className="text-sm text-slate-500">{title}</p>
        <p className="text-sm font-medium">{value} {unit}</p>
      </div>
      <Progress
        value={percentage}
        className="h-2"
        indicatorClassName="bg-[#80BF41]"
      />
      <p className="text-xs text-slate-500">{percentage}% of limit</p>
    </div>
  )
}

