// --- FILE: src/components/generateUsageData.ts ---
function generateUsageData() {
  const baseUsage = 500;
  return Array.from({ length: 30 }, (_, i) => ({
    day: `Day ${i + 1}`,
    usage: baseUsage + Math.sin(i * 0.2) * 200 + Math.random() * 50
  }))
}

