                    <TabsTrigger key={method} value={method}>
                      {method} <span className="ml-1">Request</span>
                    </TabsTrigger>
                  ))}
                </TabsList>
              </Tabs>
            </div>

            {/* Request Section */}
            {selectedEndpoint.methods.map((method) => (
              <div key={method} className="space-y-6">
