                       method === 'POST' ? 'Create new resource' :
                       method === 'PUT' ? 'Update existing resource' : 'Delete resource'}
                    </p>

                    {/* Code Display */}
                    <CodeDisplay language="http" code={mockData[selectedEndpoint.path].request[method].code} />

                    {/* Parameters Table */}
                    <div className="mt-6">
                      <h4 className="text-lg font-medium text-slate-900 mb-3">Request Parameters</h4>
                      {mockData[selectedEndpoint.path].request[method].parameters.length > 0 ? (
                        <Table>
                          <TableHeader>
                            <TableRow>
                              <TableHead className="w-[120px]">Name</TableHead>
                              <TableHead>Type</TableHead>
                              <TableHead>Description</TableHead>
                              <TableHead className="w-[100px]">Required</TableHead>
                            </TableRow>
                          </TableHeader>
                          <TableBody>
                            {mockData[selectedEndpoint.path].request[method].parameters.map((param) => (
                              <TableRow key={param.name}>
                                <TableCell>{param.name}</TableCell>
                                <TableCell>{param.type}</TableCell>
                                <TableCell>{param.description}</TableCell>
                                <TableCell>
                                  {param.required ? (
                                    <div className="flex items-center gap-1">
                                      <Check className="w-4 h-4 text-green-500" />
                                      <span>Yes</span>
                                    </div>
                                  ) : (
                                    <div className="flex items-center gap-1">
                                      <X className="w-4 h-4 text-gray-400" />
                                      <span>No</span>
                                    </div>
                                  )}
                                </TableCell>
                              </TableRow>
                            ))}
                          </TableBody>
                        </Table>
                      ) : (
                        <div className="p-4 bg-slate-50 rounded-lg text-slate-600">
                          No additional parameters
                        </div>
                      )}
                    </div>
                  </div>
                </div>

                {/* Response Section */}
                <div className="mt-10">
                  <h3 className="text-xl font-semibold text-slate-900">{method} Response</h3>
                  <CodeDisplay language="json" code={mockData[selectedEndpoint.path].response[method]} />
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  )
}

