// --- FILE: src/components/OnboardingWizard.tsx ---
function OnboardingWizard() {
  const steps = [
    { id: 'account', title: 'Account Setup', description: 'Create your developer account and preferences' },
    { id: 'project', title: 'Project Info', description: 'Configure your workspace and project settings' },
    { id: 'integration', title: 'Integrations', description: 'Connect your tools and services' },
    { id: 'review', title: 'Review & Launch', description: 'Finalize and launch your workspace' }
  ];

  const [currentStep, setCurrentStep] = useState(0);
  const [formData, setFormData] = useState({
    email: '',
    name: '',
    role: 'developer',
    projectName: '',
    projectType: 'new',
    integrations: []
  });

  const handleNext = () => {
    if (currentStep === steps.length - 1) {
      // Final submission logic
      console.log('Form submitted:', formData);
    } else {
      setCurrentStep(prev => prev + 1);
    }
  };

  const handleBack = () => {
    setCurrentStep(prev => Math.max(prev - 1, 0));
  };

  return (
    <div className="min-h-screen bg-white">
      <AIKitHeader
        title="Developer Onboarding"
        subtitle="Set up your workspace in minutes"
        navItems={[]}
        user="JD"
        onSearch={() => {}}
      />

      <div className="max-w-5xl mx-auto px-6 py-12">
        <Card className="border-none shadow-none">
          <CardContent className="p-8">
            <div className="flex flex-col lg:flex-row gap-12">
              {/* Stepper */}
              <div className="w-full lg:w-64 flex-shrink-0">
                <AIKitStepper
                  steps={steps.map(step => step.title)}
                  currentStep={currentStep}
                  className="space-y-8"
                />
              </div>

              {/* Form Content */}
              <div className="w-full flex-1">
                <h2 className="text-2xl font-bold text-slate-900 mb-6">
                  {steps[currentStep].title}
                </h2>
                <p className="text-slate-600 mb-8">
                  {steps[currentStep].description}
                </p>

                {/* Step Content */}
                {currentStep === 0 && (
                  <AccountSetupForm
                    formData={formData}
                    onChange={(e) => {
                      const { name, value, type } = e.target;
                      setFormData(prev => ({
                        ...prev,
                        [name]: type === 'checkbox' ? e.target.checked : value
                      }));
                    }}
                  />
                )}

                {currentStep === 1 && (
                  <ProjectInfoForm
                    formData={formData}
                    onChange={(e) => {
                      const { name, value } = e.target;
                      setFormData(prev => ({
                        ...prev,
                        [name]: value
                      }));
                    }}
                  />
                )}

                {currentStep === 2 && (
                  <IntegrationsForm
                    formData={formData}
                    onChange={(e) => {
                      const { name, value } = e.target;
                      setFormData(prev => ({
                        ...prev,
                        [name]: value
                      }));
                    }}
                    onIntegrationToggle={(integration) => {
                      setFormData(prev => ({
                        ...prev,
                        integrations: prev.integrations.includes(integration)
                          ? prev.integrations.filter(i => i !== integration)
                          : [...prev.integrations, integration]
                      }));
                    }}
                  />
                )}

                {currentStep === 3 && (
                  <ReviewForm
                    formData={formData}
                  />
                )}

                {/* Progress Bar */}
                <div className="mt-12 mb-8">
                  <Progress
                    value={(currentStep / steps.length) * 100}
                    className="h-2 rounded-full"
                  />
                  <div className="flex justify-between text-sm text-slate-600 mt-2">
                    {steps.map((step, index) => (
                      <div key={step.id} className={`flex items-center gap-1 ${index <= currentStep ? 'text-slate-900' : 'text-slate-400'}`}>
                        {index <= currentStep ? (
                          <Check className="w-4 h-4" />
                        ) : (
                          <Circle className="w-4 h-4" />
                        )}
                        <span>{step.title}</span>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Navigation */}
                <div className="flex justify-between items-center mt-12">
                  {currentStep > 0 && (
                    <Button
                      variant="outline"
                      className="border-slate-300 hover:bg-slate-50"
                      onClick={handleBack}
                    >
                      <ArrowLeft className="w-4 h-4 mr-2" /> Back
                    </Button>
                  )}

                  <Button
                    className="bg-blue-600 hover:bg-blue-700 text-white"
                    onClick={handleNext}
                  >
                    {currentStep === steps.length - 1 ? (
                      <>Finish Setup</>
                    ) : (
                      <>
                        <ArrowRight className="w-4 h-4 mr-2" /> Continue
                      </>
                    )}
                  </Button>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

