function MetricCard({
  title,
  value,
  change,
  trend,
  description,
  iconLabel,
  color,
  sparkline
}) {
  const getTrendIndicator = () => {
    if (trend === 'up') {
      return (
        <div className="flex items-center gap-1 text-sm font-medium text-emerald-600">
          <ArrowUp className="w-4 h-4" /> {change}
        </div>
      );
    } else {
      return (
        <div className="flex items-center gap-1 text-sm font-medium text-red-500">
          <ArrowDown className="w-4 h-4" /> {change}
        </div>
      );
    }
  };

  return (
    <Card className="bg-white border border-slate-200 shadow-sm hover:shadow-md transition-all duration-300">
      <CardHeader className="flex flex-row items-start gap-4">
        <div className={`w-12 h-12 rounded-lg ${color} flex items-center justify-center text-white font-bold`}>
          {iconLabel}
        </div>
        <div className="flex-1">
          <div className="flex justify-between items-baseline">
            <CardTitle className="text-lg font-semibold text-slate-900">
              {title}
            </CardTitle>
          </div>
          <CardDescription className="text-sm text-slate-500 mt-1">
            {description}
          </CardDescription>
        </div>
      </CardHeader>
      <CardContent>
        <div className="flex justify-between items-center">
          <div className="text-2xl font-bold text-slate-900">{value}</div>
          {getTrendIndicator()}
        </div>
        <div className="mt-4">
          <div className="h-2 w-full bg-slate-100 rounded-full">
            {sparkline.map((point, index) => (
              <div
                key={index}
                className="h-full rounded-full"
                style={{
                  width: `${point / 10}%`,
                  backgroundColor: trend === 'up' ? 'rgba(22, 163, 74, 0.5)' : 'rgba(239, 68, 68, 0.5)'
                }}
              />
            ))}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

